import itertools

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().splitlines()

    if not input_data:
        return

    # Parse N
    try:
        n = int(input_data[0].strip())
    except ValueError:
        return

    # Parse the 4 blocks
    blocks = []
    for i in range(1, 5):
        if i < len(input_data):
            blocks.append(list(input_data[i].strip()))

    # Parse the N words
    words = []
    for i in range(5, 5 + n):
        if i < len(input_data):
            words.append(input_data[i].strip())

    # For each word, check if it can be formed
    for word in words:
        length = len(word)
        # We need to assign each character of the word to a distinct block
        # Since there are only 4 blocks and word length <= 4, we can try all permutations
        # of blocks of length 'length' and check if the letters match.

        possible = False

        # Generate all permutations of block indices of length equal to word length
        # e.g., if word is "COW" (len 3), we try permutations of (0,1,2,3) taken 3 at a time
        for block_indices in itertools.permutations(range(4), length):
            # Check if this assignment works
            match = True
            for char_idx, block_idx in enumerate(block_indices):
                letter_needed = word[char_idx]
                # Check if the letter is on the corresponding block
                if letter_needed not in blocks[block_idx]:
                    match = False
                    break

            if match:
                possible = True
                break

        if possible:
            print("YES")
        else:
            print("NO")

