def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        K = int(next(iterator))
    except StopIteration:
        return

    diamonds = []
    for _ in range(N):
        try:
            diamonds.append(int(next(iterator)))
        except StopIteration:
            break

    # If there are no diamonds, the answer is 0
    if N == 0:
        print(0)
        return

    # Brute-force: enumerate all possible subsets of diamonds
    # There are 2^N subsets. For N <= 1000 this is impossible, 
    # but the problem asks for a brute-force solution intended for very small inputs.
    # We will use bitmasking to generate all subsets.

    max_count = 0
    total_subsets = 1 << N  # 2^N

    for mask in range(total_subsets):
        # Collect the sizes of diamonds in the current subset
        subset = []
        for i in range(N):
            if (mask >> i) & 1:
                subset.append(diamonds[i])

        # Check if the subset is valid
        # A subset is valid if for every pair of diamonds in it, 
        # the absolute difference is <= K.
        # If the subset has 0 or 1 diamond, it is always valid.
        valid = True
        if len(subset) > 1:
            # Check all pairs
            for i in range(len(subset)):
                for j in range(i + 1, len(subset)):
                    if abs(subset[i] - subset[j]) > K:
                        valid = False
                        break
                if not valid:
                    break

        if valid:
            if len(subset) > max_count:
                max_count = len(subset)

    print(max_count)

