import sys

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        K = int(next(iterator))
    except StopIteration:
        return

    # Read original grid
    original_grid = []
    for _ in range(N):
        original_grid.append(next(iterator))

    # Read K pieces
    pieces = []
    for _ in range(K):
        grid = []
        for _ in range(N):
            grid.append(next(iterator))
        pieces.append(grid)

    # Helper to get list of (r, c) coordinates for '#' in a grid
    def get_hashes(grid):
        hashes = []
        for r in range(N):
            for c in range(N):
                if grid[r][c] == '#':
                    hashes.append((r, c))
        return hashes

    original_hashes = get_hashes(original_grid)
    piece_hashes_list = [get_hashes(p) for p in pieces]

    # Try every pair of pieces (i, j) with i < j
    for i in range(K):
        for j in range(i + 1, K):
            # We need to find shifts (dr1, dc1) for piece i and (dr2, dc2) for piece j
            # such that when shifted, they exactly cover original_hashes without overlap.

            # Since the problem states the pieces are not rotated/flipped, only shifted.
            # The shift is applied to the piece's '#' coordinates.
            # Let piece i have hashes H_i. Shifted: {(r+dr1, c+dc1) for (r,c) in H_i}
            # Let piece j have hashes H_j. Shifted: {(r+dr2, c+dc2) for (r,c) in H_j}
            # Constraints: All shifted coordinates must be within [0, N-1] x [0, N-1].
            # Union of shifted sets must equal original_hashes.
            # Intersection must be empty.

            # To limit the search space for shifts:
            # For a piece with hashes, the minimum row is min_r, max row is max_r.
            # If we shift by dr, the new min row is min_r + dr.
            # We need 0 <= min_r + dr and max_r + dr <= N-1.
            # So dr_min = -min_r, dr_max = (N-1) - max_r.
            # Similarly for dc.

            # However, since N is very small (<= 8), we can just iterate dr, dc from -(N-1) to (N-1)
            # and check bounds.

            dr_range = range(-(N-1), N)
            dc_range = range(-(N-1), N)

            # Optimization: Pre-calculate valid shifts for each piece that keep it in bounds
            # But given N<=8, brute force over all shifts is fine.

            found = False
            for dr1 in dr_range:
                for dc1 in dc_range:
                    # Check if piece i shifted by (dr1, dc1) is valid
                    shifted_i = []
                    valid_i = True
                    for r, c in piece_hashes_list[i]:
                        nr, nc = r + dr1, c + dc1
                        if 0 <= nr < N and 0 <= nc < N:
                            shifted_i.append((nr, nc))
                        else:
                            valid_i = False
                            break
                    if not valid_i:
                        continue

                    # If piece i is valid, try piece j
                    for dr2 in dr_range:
                        for dc2 in dc_range:
                            shifted_j = []
                            valid_j = True
                            for r, c in piece_hashes_list[j]:
                                nr, nc = r + dr2, c + dc2
                                if 0 <= nr < N and 0 <= nc < N:
                                    shifted_j.append((nr, nc))
                                else:
                                    valid_j = False
                                    break
                            if not valid_j:
                                continue

                            # Check union and intersection
                            set_i = set(shifted_i)
                            set_j = set(shifted_j)

                            # Intersection must be empty
                            if set_i & set_j:
                                continue

                            # Union must equal original_hashes
                            if set_i | set_j == set(original_hashes):
                                # Found the solution
                                print(f"{i+1} {j+1}")
                                return

