import sys
import json
from itertools import combinations

def get_obtainable_sums(coins):
    """
    Given a list of coins, return a set of all obtainable sums using non-empty subsequences.
    This is a brute-force enumeration of all non-empty subsequences.
    """
    n = len(coins)
    sums = set()
    # Iterate over all possible subsequence lengths from 1 to n
    for r in range(1, n + 1):
        for indices in combinations(range(n), r):
            s = sum(coins[i] for i in indices)
            sums.add(s)
    return sums

def minimumAddedCoins_bruteforce(coins, target):
    """
    Brute-force solution:
    We need to find the minimum number of coins to add so that every integer in [1, target]
    is obtainable as a sum of some subsequence of the (original + added) coins.

    Since this is brute-force and intended only for very small inputs, we will:
    1. Generate all possible subsets of coins to add (up to a small limit, say up to 3 or 4 coins,
       or until we find a solution).
    2. For each candidate set of added coins, check if all values in [1, target] are obtainable.
    3. Return the smallest size of such a set.

    Note: This approach is exponential and will only work for tiny inputs.
    """
    # We'll try adding k coins, for k = 0, 1, 2, ... until we find a solution.
    # To keep it brute-force and correct, we consider all possible coin values to add.
    # However, the search space for coin values is [1, target], so we limit k to small values.

    # First, check if we already satisfy the condition with 0 added coins.
    original_sums = get_obtainable_sums(coins)
    if all(x in original_sums for x in range(1, target + 1)):
        return 0

    # Try adding 1 coin
    for add_val in range(1, target + 1):
        new_coins = coins + [add_val]
        new_sums = get_obtainable_sums(new_coins)
        if all(x in new_sums for x in range(1, target + 1)):
            return 1

    # Try adding 2 coins
    for v1 in range(1, target + 1):
        for v2 in range(1, target + 1):
            new_coins = coins + [v1, v2]
            new_sums = get_obtainable_sums(new_coins)
            if all(x in new_sums for x in range(1, target + 1)):
                return 2

    # Try adding 3 coins
    for v1 in range(1, target + 1):
        for v2 in range(1, target + 1):
            for v3 in range(1, target + 1):
                new_coins = coins + [v1, v2, v3]
                new_sums = get_obtainable_sums(new_coins)
                if all(x in new_sums for x in range(1, target + 1)):
                    return 3

    # Try adding 4 coins (only if needed, but this is already very slow)
    for v1 in range(1, target + 1):
        for v2 in range(1, target + 1):
            for v3 in range(1, target + 1):
                for v4 in range(1, target + 1):
                    new_coins = coins + [v1, v2, v3, v4]
                    new_sums = get_obtainable_sums(new_coins)
                    if all(x in new_sums for x in range(1, target + 1)):
                        return 4

    # If nothing found (should not happen for valid inputs as we can always add coins 1,2,4,...),
    # return a safe upper bound (e.g., target, though not minimal).
    return target

class Solution:
    def minimumAddedCoins(self, coins, target):
        return minimumAddedCoins_bruteforce(coins, target)

