                output.append("NO")
                continue

            # We need to check two-way mapping consistency:
            # 1. If a[i] == a[j] then s[i] == s[j]
            # 2. If s[i] == s[j] then a[i] == a[j]
            # This is equivalent to checking if the pattern of equality in 'a'
            # is exactly the same as the pattern of equality in 's'.
            # A brute-force way is to build the mapping from both sides and verify.

            # Create mapping from number to char
            num_to_char = {}
            # Create mapping from char to number
            char_to_num = {}
            possible = True

            for i in range(n):
                num_val = a[i]
                char_val = s[i]

                # Check consistency for num -> char
                if num_val in num_to_char:
                    if num_to_char[num_val] != char_val:
                        possible = False
                        break
                else:
                    num_to_char[num_val] = char_val

                # Check consistency for char -> num
                if char_val in char_to_num:
                    if char_to_num[char_val] != num_val:
                        possible = False
                        break
                else:
                    char_to_num[char_val] = num_val

            if possible:
                output.append("YES")
            else:
                output.append("NO")

