class Solution:
    def minAbsoluteDifference(self, nums: List[int], x: int) -> int:
        # Brute-force: check every pair (i, j) with abs(i - j) >= x
        n = len(nums)
        min_diff = float('inf')

        for i in range(n):
            for j in range(n):
                if abs(i - j) >= x:
                    diff = abs(nums[i] - nums[j])
                    if diff < min_diff:
                        min_diff = diff

        return min_diff

