import json
from typing import *

def is_balanced(sub: str) -> bool:
    """Check if a string is balanced (all characters appear the same number of times)."""
    if not sub:
        return False
    counts = {}
    for ch in sub:
        counts[ch] = counts.get(ch, 0) + 1
    freqs = list(counts.values())
    return all(f == freqs[0] for f in freqs)

def min_partitions(s: str) -> int:
    """Brute-force: try all possible partitions and return the minimum number of balanced substrings."""
    n = len(s)
    # dp[i] = minimum number of balanced substrings to partition s[i:]
    # We'll use recursion with memoization for clarity, but since it's brute-force we can also do full enumeration.
    # However, to keep it "obviously correct" and simple, we'll do full recursion without memo (exponential).

    def recurse(start: int) -> int:
        if start == n:
            return 0
        best = float('inf')
        # Try every possible end for the next substring
        for end in range(start + 1, n + 1):
            sub = s[start:end]
            if is_balanced(sub):
                res = recurse(end)
                if res != float('inf'):
                    best = min(best, 1 + res)
        return best

    return recurse(0)

class Solution:
    def minimumSubstringsInPartition(self, s: str) -> int:
        return min_partitions(s)

