from itertools import product

def is_stable(arr, zero_count, one_count, limit):
    # Count zeros and ones
    cnt0 = 0
    cnt1 = 0
    for x in arr:
        if x == 0:
            cnt0 += 1
        else:
            cnt1 += 1

    if cnt0 != zero_count or cnt1 != one_count:
        return False

    n = len(arr)
    # Check every subarray of length > limit
    for length in range(limit + 1, n + 1):
        for i in range(0, n - length + 1):
            sub = arr[i:i+length]
            # Must contain both 0 and 1
            if 0 not in sub or 1 not in sub:
                return False
    return True

def solve():
    lines = [line.strip() for line in sys.stdin if line.strip()]
    if len(lines) < 3:
        return
    zero = json.loads(lines[0])
    one = json.loads(lines[1])
    limit = json.loads(lines[2])

    total = zero + one
    # Brute-force over all binary arrays of length total
    count = 0
    for bits in product([0, 1], repeat=total):
        if is_stable(bits, zero, one, limit):
            count += 1

    print(json.dumps(count))

