import sys
import json
from typing import List

# Brute-force solution: enumerate all possible sequences of drink choices.
# For each hour i (0 to n-1), we can choose drink A or drink B.
# However, if we switch from A to B or B to A compared to the previous hour,
# we lose the energy boost for that hour (i.e., we get 0 for that hour).
# We start at hour 0 with either A or B (no penalty for starting).
#
# Since n is small for brute force, we can try all 2^n sequences.
# We'll generate all sequences of length n where each element is 0 (drink A) or 1 (drink B).
# Then simulate and compute total energy, tracking the maximum.

def solve_bruteforce(energyDrinkA: List[int], energyDrinkB: List[int]) -> int:
    n = len(energyDrinkA)
    max_total = 0

    # Enumerate all 2^n sequences using bitmask from 0 to (1<<n) - 1
    for mask in range(1 << n):
        total = 0
        prev_drink = None  # None means no previous drink (at hour 0)

        for i in range(n):
            # Determine current drink: 0 for A, 1 for B
            current_drink = (mask >> i) & 1

            if prev_drink is None:
                # First hour: no penalty, just take the drink's energy
                if current_drink == 0:
                    total += energyDrinkA[i]
                else:
                    total += energyDrinkB[i]
            else:
                if current_drink == prev_drink:
                    # Same drink as previous hour: no penalty
                    if current_drink == 0:
                        total += energyDrinkA[i]
                    else:
                        total += energyDrinkB[i]
                else:
                    # Switched drinks: lose energy for this hour (add 0)
                    pass

            prev_drink = current_drink

        if total > max_total:
            max_total = total

    return max_total

class Solution:
    def maxEnergyBoost(self, energyDrinkA: List[int], energyDrinkB: List[int]) -> int:
        return solve_bruteforce(energyDrinkA, energyDrinkB)

if __name__ == "__main__":
    # Read input from stdin
    lines = sys.stdin.read().splitlines()
    # Filter out empty lines
    lines = [line.strip() for line in lines if line.strip()]

    if len(lines) < 2:
        raise ValueError("Input must contain exactly two lines: energyDrinkA and energyDrinkB")

    energyDrinkA = json.loads(lines[0])
    energyDrinkB = json.loads(lines[1])

    result = Solution().maxEnergyBoost(energyDrinkA, energyDrinkB)
    print(json.dumps(result))

