from itertools import combinations

def is_balanced(nums, indices):
    # indices is a tuple of indices in increasing order
    if len(indices) <= 1:
        return True
    for j in range(1, len(indices)):
        i_prev = indices[j-1]
        i_curr = indices[j]
        if nums[i_curr] - nums[i_prev] < i_curr - i_prev:
            return False
    return True

def max_balanced_subsequence_sum_brute(nums):
    n = len(nums)
    max_sum = -float('inf')

    # Enumerate all non-empty subsequences via all possible index combinations
    for length in range(1, n + 1):
        for indices in combinations(range(n), length):
            # indices is already sorted because combinations yields in sorted order
            if is_balanced(nums, indices):
                current_sum = sum(nums[i] for i in indices)
                if current_sum > max_sum:
                    max_sum = current_sum
    return max_sum

class Solution:
    def maxBalancedSubsequenceSum(self, nums: list[int]) -> int:
        return max_balanced_subsequence_sum_brute(nums)

