import sys

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        try:
            n = int(next(iterator))
            a = []
            for _ in range(n):
                a.append(int(next(iterator)))
        except StopIteration:
            break

        # Brute-force approach:
        # Try every possible interval [l, r] with 1 <= l <= r <= n
        # Note: The problem uses 1-based indexing for description, 
        # but our list 'a' is 0-based. So interval [l, r] corresponds to indices l-1 to r-1.

        max_rating = -float('inf')

        # l and r are 1-based indices
        for l in range(1, n + 1):
            for r in range(l, n + 1):
                # Simulate the process for this specific interval [l, r]
                current_rating = 0

                # Iterate through all contests from 1 to n (index 0 to n-1)
                for i in range(1, n + 1):
                    # Check if current contest i is in the skipped interval [l, r]
                    if l <= i <= r:
                        # Skip this contest, rating remains unchanged
                        continue
                    else:
                        # Get the performance rating for contest i (0-based index i-1)
                        val = a[i-1]

                        if val > current_rating:
                            current_rating += 1
                        elif val == current_rating:
                            current_rating += 0
                        else: # val < current_rating
                            current_rating -= 1

                if current_rating > max_rating:
                    max_rating = current_rating

        results.append(str(max_rating))

    # Print all results separated by newlines
    print('\n'.join(results))

